# 1. สร้างใบกิจกรรมและสื่อการสอน 18 ไฟล์ (03_ใบกิจกรรมและสื่อการสอน_แจกนักเรียน)
# ==============================================================================
def build_all_worksheets():
    for pl in PLANS_FULL:
        doc = setup_doc()
        p_num = pl["p_num"]
        u_num = pl["u_num"]
        u_title = pl["u_title"]
        add_p(doc, f"สื่อการเรียนรู้ประกอบแผนการจัดการเรียนรู้ที่ {p_num}: {pl['title']}", size=16, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, color_rgb=RGBColor(0x1A, 0x36, 0x5D))
        add_p(doc, f"หน่วยการเรียนรู้ที่ {u_num}: {u_title} | รายวิชา ดนตรี 2 (ศ22102) ชั้นมัธยมศึกษาปีที่ 2 ภาคเรียนที่ 2 ปีการศึกษา 2569", size=14, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
        add_p(doc, f"กิจกรรมหลัก: {pl['media_title']}  |  โรงเรียนพะเยาพิทยาคม  |  ชื่อ-สกุล: ____________________________________ เลขที่: _____ ห้อง: ม.2/_____", size=14, align=WD_ALIGN_PARAGRAPH.CENTER)
        add_p(doc, "―" * 55, size=13, align=WD_ALIGN_PARAGRAPH.CENTER)

        # 3-Tier Mastery Box
        t_tier = doc.add_table(rows=2, cols=1)
        t_tier.style = 'Table Grid'
        format_cell(t_tier.rows[0].cells[0], "🎯 เส้นทางการเรียนรู้ปรับเหมาะ 3 ระดับ (3-Tier Adaptive Mastery Loop — เลือกท้าทายตามศักยภาพ)", size=14, bold=True, bg_hex="D9E1F2")
        format_cell(t_tier.rows[1].cells[0], pl["step_p"], size=13, bg_hex="F8FAFC")

        for sec_title, headers, rows_data in pl["ws_tasks"]:
            add_p(doc, sec_title, size=15, bold=True, space_before=10, space_after=4, color_rgb=RGBColor(0x2B, 0x6C, 0xB0))
            tbl = doc.add_table(rows=1, cols=len(headers))
            tbl.style = 'Table Grid'
            for i, h in enumerate(headers):
                format_cell(tbl.rows[0].cells[i], h, size=13, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, bg_hex="EDF2F7")
            for r_data in rows_data:
                rc = tbl.add_row().cells
                for i, val in enumerate(r_data):
                    format_cell(rc[i], val if val else " ", size=13)

        add_p(doc, "บันทึกการตรวจประเมินของคู่บัดดี้และครูผู้สอน:  [  ] 🥉 Bronze (ผ่านเกณฑ์พื้นฐาน)   [  ] 🥈 Silver (ผ่านเกณฑ์มาตรฐาน)   [  ] 🥇 Gold (ยอดเยี่ยมและสร้างสรรค์)   ลงชื่อคู่บัดดี้: ____________________", size=13, bold=True, space_before=10)

        out_path = os.path.join(DIR_MEDIA, pl["media_fn"])
        doc.save(out_path)
    print(f"✅ สร้างใบกิจกรรมและสื่อการสอนครบ 18 ไฟล์ ใน {DIR_MEDIA}")

