def build_all_rubrics():
    for r_id, fn, title, headers, rows_data in RUBRICS_INFO:
        doc = setup_doc()
        add_p(doc, title, size=16, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, color_rgb=RGBColor(0x1A, 0x36, 0x5D))
        add_p(doc, "รายวิชา ดนตรี 2 (รหัสวิชา ศ22102) ชั้นมัธยมศึกษาปีที่ 2 ภาคเรียนที่ 2 ปีการศึกษา 2569 โรงเรียนพะเยาพิทยาคม", size=14, align=WD_ALIGN_PARAGRAPH.CENTER)
        add_p(doc, "คำชี้แจง: ใช้สำหรับประเมินตามสภาพจริง (Authentic Assessment) ควบคู่กับตารางเกณฑ์รูบริกประจำแผนการจัดการเรียนรู้ (วก.5)", size=14, bold=True)

        tbl = doc.add_table(rows=1, cols=len(headers))
        tbl.style = 'Table Grid'
        for i, h in enumerate(headers):
            format_cell(tbl.rows[0].cells[i], h, size=14, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, bg_hex="D9E1F2")
        for r_data in rows_data:
            rc = tbl.add_row().cells
            for i, val in enumerate(r_data):
                format_cell(rc[i], val if val else " ", size=13)

        add_p(doc, "เกณฑ์การผ่านมาตรฐาน: ผู้เรียนต้องได้ระดับคุณภาพตั้งแต่ 3 (ดี / ร้อยละ 75-80) ขึ้นไปในแต่ละประเด็นการประเมิน", size=14, bold=True, space_before=8)
        out_path = os.path.join(DIR_RUBRIC, fn)
        doc.save(out_path)
    print(f"✅ สร้างเครื่องมือวัดผลและรูบริกครบ 8 ไฟล์ ใน {DIR_RUBRIC}")

