def build_all_tests_and_blueprint():
    for u_num, fn, title, ind_str, q_list in TESTS_DATA:
        doc = setup_doc()
        add_p(doc, title, size=16, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, color_rgb=RGBColor(0x1A, 0x36, 0x5D))
        add_p(doc, f"รายวิชา ดนตรี 2 (รหัสวิชา ศ22102) ชั้นมัธยมศึกษาปีที่ 2 ภาคเรียนที่ 2 ปีการศึกษา 2569 | มาตรฐาน/ตัวชี้วัด: {ind_str}", size=14, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
        add_p(doc, "คำชี้แจง: แบบทดสอบปรนัย 4 ตัวเลือก จำนวน 10 ข้อ (คะแนนเต็ม 10 คะแนน นำไปคำนวณตามสัดส่วนโครงสร้างรายวิชา วก.3)", size=14)
        add_p(doc, "—" * 55, size=13, align=WD_ALIGN_PARAGRAPH.CENTER)

        for q_text, a, b, c, d, ans, ind in q_list:
            add_p(doc, f"{q_text}  [{ind}]", size=15, bold=True, space_before=6, space_after=2)
            add_p(doc, f"    {a}          {b}\n    {c}          {d}", size=14, space_before=0, space_after=4)

        doc.add_page_break()
        add_p(doc, f"เฉลยและตารางวิเคราะห์ความสอดคล้อง (IOC) ประจำหน่วยการเรียนรู้ที่ {u_num}", size=16, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
        tbl = doc.add_table(rows=1, cols=4)
        tbl.style = 'Table Grid'
        for i, h in enumerate(["ข้อที่", "ตัวชี้วัดชั้นปี", "เฉลยคำตอบที่ถูกต้อง", "ค่าดัชนีความสอดคล้อง (IOC)"]):
            format_cell(tbl.rows[0].cells[i], h, size=14, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, bg_hex="D9E1F2")
        for idx, (_, _, _, _, _, ans, ind) in enumerate(q_list, 1):
            rc = tbl.add_row().cells
            format_cell(rc[0], str(idx), size=13, align=WD_ALIGN_PARAGRAPH.CENTER)
            format_cell(rc[1], ind, size=13, align=WD_ALIGN_PARAGRAPH.CENTER)
            format_cell(rc[2], ans, size=13, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
            format_cell(rc[3], "1.00 (ผ่านเกณฑ์)", size=13, align=WD_ALIGN_PARAGRAPH.CENTER)

        out_path = os.path.join(DIR_TEST, fn)
        doc.save(out_path)

    # สร้างพิมพ์เขียวข้อสอบ (Test Blueprint ศ22102)
    doc_bp = setup_doc()
    add_p(doc_bp, "พิมพ์เขียวข้อสอบ (Test Blueprint) และการวิเคราะห์คุณภาพเครื่องมือวัดผล", size=18, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, color_rgb=RGBColor(0x1A, 0x36, 0x5D))
    add_p(doc_bp, "รายวิชา ดนตรี 2 รหัสวิชา ศ22102 ชั้นมัธยมศึกษาปีที่ 2 ภาคเรียนที่ 2 ปีการศึกษา 2569 โรงเรียนพะเยาพิทยาคม", size=15, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
    add_p(doc_bp, "ตารางวิเคราะห์ผังการสร้างข้อสอบวัดผลสัมฤทธิ์ทางการเรียน 4 หน่วยการเรียนรู้ (รวม 40 ข้อ) ตามระดับพฤติกรรมการคิดของบลูม (Revised Bloom's Taxonomy)", size=15)

    t_bp = doc_bp.add_table(rows=1, cols=8)
    t_bp.style = 'Table Grid'
    headers_bp = ["หน่วยการเรียนรู้", "ตัวชี้วัด", "จำ/เข้าใจ (R/U)", "ประยุกต์ใช้ (Ap)", "วิเคราะห์ (An)", "ประเมินค่า/สร้างสรรค์ (E/C)", "รวมจำนวนข้อ", "น้ำหนักคะแนน K ในหน่วย"]
