def add_appendix_divider(doc, title, subtitle, items):
    doc.add_page_break()
    add_p(doc, title, size=22, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, color_rgb=RGBColor(0x1A, 0x36, 0x5D))
    add_p(doc, subtitle, size=16, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, color_rgb=RGBColor(0x2B, 0x6C, 0xB0))
    add_p(doc, "รายวิชา ดนตรี 2 (ศ22102) ชั้นมัธยมศึกษาปีที่ 2 ภาคเรียนที่ 2 ปีการศึกษา 2569 โรงเรียนพะเยาพิทยาคม", size=14, align=WD_ALIGN_PARAGRAPH.CENTER)
    add_p(doc, "―" * 45, size=14, align=WD_ALIGN_PARAGRAPH.CENTER)
    add_p(doc, "สารบัญเอกสารแนบท้าย (ภาคผนวก):", size=15, bold=True)
    for it in items:
        add_p(doc, f"  • {it}", size=14)
    add_p(doc, "―" * 45, size=14, align=WD_ALIGN_PARAGRAPH.CENTER)
    doc.add_page_break()

def compose_appendices_into_plan(doc_path, pl):
    p_num = pl["p_num"]
    u_num = pl["u_num"]
    master = docx.Document(doc_path)
    ws_path = os.path.join(DIR_MEDIA, pl["media_fn"])
    rubric_paths = []
    for r_id in pl["eval_tools"]:
        for f in os.listdir(DIR_RUBRIC):
            if f.startswith(f"เครื่องมือวัดผล_ฉบับที่_{r_id}_"):
                rubric_paths.append((os.path.join(DIR_RUBRIC, f), f))
                break
    test_path = None
    if p_num in [4, 11, 15, 18]:
        for f in os.listdir(DIR_TEST):
            if f.startswith(f"แบบทดสอบท้ายหน่วย_หน่วยที่_{u_num}_"):
                test_path = (os.path.join(DIR_TEST, f), f)
                break

    items = [f"ภาคผนวก ก: ใบกิจกรรมประจำแผน ({pl['media_fn']})"]
    items.extend([f"ภาคผนวก ข: เครื่องมือวัดผล ({fn})" for _, fn in rubric_paths])
    if test_path:
        items.append(f"ภาคผนวก ค: แบบทดสอบวัดผลสัมฤทธิ์ท้ายหน่วยที่ {u_num} ({test_path[1]})")

    add_appendix_divider(master, "ภาคผนวกประจำแผนการจัดการเรียนรู้", f"แผนการจัดการเรียนรู้ที่ {p_num:02d}: {pl['title']}", items)
    comp = Composer(master)
    if os.path.exists(ws_path):
        comp.append(docx.Document(ws_path))
    for rp, _ in rubric_paths:
        comp.append(docx.Document(rp))
    if test_path and os.path.exists(test_path[0]):
        comp.append(docx.Document(test_path[0]))
    comp.save(doc_path)

def compose_appendices_into_unit(doc_path, u_num, u_title):
    master = docx.Document(doc_path)
    unit_plans = [p for p in PLANS_FULL if p["u_num"] == u_num]
    items = [f"ภาคผนวก ก: ชุดใบกิจกรรมประจำหน่วยที่ {u_num} (รวม {len(unit_plans)} แผน)"]
    items.append(f"ภาคผนวก ข: ชุดเครื่องมือวัดผลและรูบริกประจำหน่วยที่ {u_num}")
    items.append(f"ภาคผนวก ค: แบบทดสอบวัดผลสัมฤทธิ์ท้ายหน่วยที่ {u_num} และพิมพ์เขียวข้อสอบ")
    add_appendix_divider(master, "ภาคผนวกประจำหน่วยการเรียนรู้", f"หน่วยการเรียนรู้ที่ {u_num}: {u_title}", items)
    comp = Composer(master)
    for pl in unit_plans:
        ws_path = os.path.join(DIR_MEDIA, pl["media_fn"])
        if os.path.exists(ws_path):
            comp.append(docx.Document(ws_path))
    for f in sorted(os.listdir(DIR_TEST)):
        if f.startswith(f"แบบทดสอบท้ายหน่วย_หน่วยที่_{u_num}_"):
            comp.append(docx.Document(os.path.join(DIR_TEST, f)))
    comp.save(doc_path)

